begin;
create table public.unimis_support151(
 id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),
 operator_id uuid not null references auth.users(id),scope text not null check(scope in('login','operations')),
 reason text not null check(length(btrim(reason))>=10),status text not null default 'pending' check(status in('pending','approved','rejected','revoked')),
 requested_at timestamptz not null default now(),reviewer_id uuid references auth.users(id),review_note text,
 expires_at timestamptz,check(reviewer_id is distinct from operator_id));
create table public.unimis_technical_events151(id uuid primary key default gen_random_uuid(),institution_id uuid references public.institutions(id),actor uuid not null references auth.users(id),action text not null,reference text,note text not null,created_at timestamptz not null default now());
create table public.unimis_audit_runs151(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),actor uuid not null references auth.users(id),from_date date not null,to_date date not null,academic_period_id uuid,checks jsonb not null,created_at timestamptz not null default now());
create table public.unimis_audit_findings151(id uuid primary key default gen_random_uuid(),run_id uuid not null references public.unimis_audit_runs151(id),institution_id uuid not null references public.institutions(id),actor uuid not null references auth.users(id),check_code text not null,record_reference text not null,severity text not null check(severity in('low','medium','high')),finding text not null,recommendation text not null,created_at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['unimis_support151','unimis_technical_events151','unimis_audit_runs151','unimis_audit_findings151'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);end loop;end $$;
create function public.unimis_audit_allowed151(p_inst uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.unimis_effective_memberships116 m join public.roles r on r.id=m.role_id where m.user_id=auth.uid() and m.institution_id=p_inst and m.status='active' and r.is_active and r.code in('auditor','owner'))
$$;
create function public.unimis_support_request151(p_inst uuid,p_scope text,p_reason text) returns uuid language plpgsql security definer set search_path='' as $$
declare id uuid;begin
 if not public.unimis_is_platform_operator116() then raise exception 'Protected platform operator required';end if;
 if exists(select 1 from public.unimis_support151 where operator_id=auth.uid() and institution_id=p_inst and scope=p_scope and (status='pending' or status='approved' and expires_at>now())) then raise exception 'An active request already exists';end if;
 insert into public.unimis_support151(institution_id,operator_id,scope,reason) values(p_inst,auth.uid(),p_scope,btrim(p_reason)) returning unimis_support151.id into id;
 insert into public.unimis_technical_events151(institution_id,actor,action,reference,note) values(p_inst,auth.uid(),'support_requested',id::text,p_reason);return id;end $$;
create function public.unimis_support_decide151(p_id uuid,p_action text,p_note text,p_hours integer default 2) returns void language plpgsql security definer set search_path='' as $$
declare q public.unimis_support151;begin
 select * into q from public.unimis_support151 where id=p_id for update;
 if q.id is null or not public.unimis_is_access_authority116(q.institution_id) or auth.uid()=q.operator_id then raise exception 'Independent school approval authority required';end if;
 if length(btrim(coalesce(p_note,'')))<5 or p_hours not between 1 and 8 then raise exception 'Decision note and 1–8 hours required';end if;
 if p_action not in('approved','rejected','revoked') or (p_action in('approved','rejected') and q.status<>'pending') or (p_action='revoked' and q.status<>'approved') then raise exception 'Invalid decision transition';end if;
 update public.unimis_support151 set status=p_action,reviewer_id=auth.uid(),review_note=p_note,expires_at=case when p_action='approved' then now()+make_interval(hours=>p_hours) else null end where id=p_id;
 insert into public.unimis_technical_events151(institution_id,actor,action,reference,note) values(q.institution_id,auth.uid(),'support_'||p_action,p_id::text,p_note);end $$;
create function public.unimis_support_queue151(p_inst uuid) returns jsonb language plpgsql security definer set search_path='' as $$begin
 if not public.unimis_is_access_authority116(p_inst) then raise exception 'School approval authority required';end if;
 return coalesce((select jsonb_agg(to_jsonb(x) order by x.requested_at desc) from (select q.*,u.email operator_email from public.unimis_support151 q join auth.users u on u.id=q.operator_id where q.institution_id=p_inst order by requested_at desc limit 100)x),'[]'::jsonb);end $$;
create function public.unimis_platform_dashboard151() returns jsonb language plpgsql security definer set search_path='' as $$begin
 if not public.unimis_is_platform_operator116() then raise exception 'Protected platform operator required';end if;
 return jsonb_build_object('generated_at',now(),'database_version',current_setting('server_version'),'schools',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'name',i.name)) from public.institutions i),'[]'::jsonb),'support',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from public.unimis_support151 where operator_id=auth.uid() order by requested_at desc limit 100)x),'[]'::jsonb),'events',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from public.unimis_technical_events151 where actor=auth.uid() order by created_at desc limit 100)x),'[]'::jsonb),'security',jsonb_build_object('platform_school_memberships',(select count(*) from public.unimis_platform_operators116 o join public.institution_users m on m.user_id=o.user_id where o.active),'unapproved_additional_roles',(select count(*) from public.unimis_additional_roles116 a join public.institution_users m on m.id=a.institution_user_id left join public.unimis_access_requests116 q on q.id=a.request_id where q.id is null or q.status not in('approved','executed') or q.role_id is distinct from a.role_id or q.institution_id is distinct from m.institution_id or q.target_user_id is distinct from m.user_id or q.reviewed_by is null),'self_approved_requests',(select count(*) from public.unimis_access_requests116 where reviewed_by=requested_by or reviewed_by=target_user_id)));
end $$;
create function public.unimis_technical_record151(p_inst uuid,p_action text,p_reference text,p_note text) returns void language plpgsql security definer set search_path='' as $$begin
 if not public.unimis_is_platform_operator116() then raise exception 'Protected platform operator required';end if;
 if p_action not in('backup_evidence','restore_evidence','deployment_evidence','incident','integration_check','licence_record') or length(btrim(p_note))<10 then raise exception 'Valid maintenance category and descriptive evidence required';end if;
 insert into public.unimis_technical_events151(institution_id,actor,action,reference,note) values(p_inst,auth.uid(),p_action,p_reference,p_note);end $$;
create function public.unimis_support_diagnose151(p_inst uuid,p_scope text,p_email text default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare u auth.users;result jsonb;begin
 if not public.unimis_is_platform_operator116() or not exists(select 1 from public.unimis_support151 where institution_id=p_inst and operator_id=auth.uid() and scope=p_scope and status='approved' and expires_at>now()) then raise exception 'Approved, unexpired support scope required';end if;
 if p_scope='login' then
 if nullif(btrim(p_email),'') is null then raise exception 'Exact account email required';end if;
 select * into u from auth.users where lower(email)=lower(btrim(p_email)) and (exists(select 1 from public.institution_users where user_id=auth.users.id and institution_id=p_inst) or exists(select 1 from public.applicants where user_id=auth.users.id and institution_id=p_inst) or exists(select 1 from public.user_invitations where lower(email)=lower(auth.users.email) and institution_id=p_inst));
 result=jsonb_build_object('account_found_for_school',u.id is not null,'email_confirmed',u.email_confirmed_at is not null,'last_sign_in_at',u.last_sign_in_at,'banned_until',u.banned_until,'memberships',coalesce((select jsonb_agg(jsonb_build_object('role',r.code,'status',m.status,'role_active',r.is_active)) from public.unimis_effective_memberships116 m join public.roles r on r.id=m.role_id where m.user_id=u.id and m.institution_id=p_inst),'[]'::jsonb),'invitations',coalesce((select jsonb_agg(jsonb_build_object('status',status,'expires_at',expires_at)) from public.user_invitations where institution_id=p_inst and lower(email)=lower(btrim(p_email))),'[]'::jsonb));
 else
 result=jsonb_build_object('students',(select count(*) from public.students where institution_id=p_inst),'submitted_results',(select count(*) from public.course_results where institution_id=p_inst and result_status='submitted'),'published_results',(select count(*) from public.course_results where institution_id=p_inst and result_status='published'),'pending_registration',(select count(*) from public.student_period_registrations where institution_id=p_inst and registration_status='submitted'),'pending_invitations',(select count(*) from public.user_invitations where institution_id=p_inst and status='pending'));
 end if;
 insert into public.unimis_technical_events151(institution_id,actor,action,reference,note) values(p_inst,auth.uid(),'support_diagnosis',p_scope,'Read-only scoped diagnostics performed');return result;end $$;
-- Immutable check snapshots retain exact counts and a bounded sample of evidence references.
create function public.unimis_audit_run151(p_inst uuid,p_from date,p_to date,p_period uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare checks jsonb;rid uuid;begin
 if not public.unimis_audit_allowed151(p_inst) then raise exception 'School Auditor or Owner required';end if;
 if p_from is null or p_to is null or p_from>p_to then raise exception 'Valid date range required';end if;
 if p_period is not null and not exists(select 1 from public.academic_periods where id=p_period and institution_id=p_inst) then raise exception 'Semester belongs to another school';end if;
 with evidence as (
 select 'FIN01' code,'Unbalanced or empty posted journal' title,'high' severity,j.id::text reference,jsonb_build_object('journal',j.journal_number,'debit',coalesce(sum(l.debit),0),'credit',coalesce(sum(l.credit),0)) detail
 from public.finance_journals j left join public.finance_journal_lines l on l.journal_id=j.id and l.institution_id=p_inst where j.institution_id=p_inst and j.status='posted' and j.journal_date between p_from and p_to group by j.id having count(l.id)=0 or abs(coalesce(sum(l.debit-l.credit),0))>0.01
 union all select 'FIN02','Completed cash payment without receipt','high',p.id::text,jsonb_build_object('payment',p.payment_reference,'amount',p.amount,'currency',p.currency_code) from public.student_payments p where p.institution_id=p_inst and p.status='completed' and p.payment_method<>'waiver' and p.payment_date::date between p_from and p_to and not exists(select 1 from public.payment_receipts r where r.payment_id=p.id and r.institution_id=p_inst)
 union all select 'FIN03','Completed cash payment without posted source journal','high',p.id::text,jsonb_build_object('payment',p.payment_reference,'amount',p.amount,'currency',p.currency_code) from public.student_payments p where p.institution_id=p_inst and p.status='completed' and p.payment_method<>'waiver' and p.payment_date::date between p_from and p_to and not exists(select 1 from public.finance_journals j where j.institution_id=p_inst and j.source_type='student_payment' and j.source_id=p.id and j.status='posted')
 union all select 'FIN04','Voided payment still completed or missing reversal journal','high',p.id::text,jsonb_build_object('payment',p.payment_reference,'status',p.status) from public.student_payments p where p.institution_id=p_inst and coalesce(p.voided_at,p.payment_date)::date between p_from and p_to and ((p.voided_at is not null and p.status='completed') or (p.status='reversed' and not exists(select 1 from public.finance_journals j where j.institution_id=p_inst and j.source_type='student_payment_void' and j.source_id=p.id and j.status='posted')))
 union all select 'FIN05','Invoice paid total differs from completed payments','medium',i.id::text,jsonb_build_object('invoice',i.invoice_number,'stored_paid',i.amount_paid,'completed_payments',coalesce((select sum(p.amount) from public.student_payments p where p.invoice_id=i.id and p.institution_id=p_inst and p.status='completed' and p.currency_code=i.currency_code),0),'currency',i.currency_code) from public.student_invoices i where i.institution_id=p_inst and i.invoice_date between p_from and p_to and abs(i.amount_paid-coalesce((select sum(p.amount) from public.student_payments p where p.invoice_id=i.id and p.institution_id=p_inst and p.status='completed' and p.currency_code=i.currency_code),0))>0.01
 union all select 'FIN06','Verified GHS application fee without income journal','high',p.id::text,jsonb_build_object('provider_reference',p.provider_reference,'amount',p.amount,'currency',p.currency) from public.admission_application_payments p where p.institution_id=p_inst and p.status='verified' and p.currency='GHS' and coalesce(p.paid_at,p.verified_at,p.created_at)::date between p_from and p_to and not exists(select 1 from public.finance_journals j where j.institution_id=p_inst and j.source_type='application_fee' and j.source_id=p.id and j.status='posted')
 union all select 'ACA01','Published result missing approval identity/time','medium',r.id::text,jsonb_build_object('student_id',r.student_id,'score',r.total_score,'approved_by',r.approved_by,'published_at',r.published_at) from public.course_results r join public.course_offerings co on co.id=r.course_offering_id where r.institution_id=p_inst and r.result_status='published' and coalesce(r.published_at,r.created_at)::date between p_from and p_to and (p_period is null or co.academic_period_id=p_period) and (r.approved_by is null or r.approved_at is null or r.published_at is null)
 union all select 'ACA02','Published result missing grade or grade point','high',r.id::text,jsonb_build_object('student_id',r.student_id,'grade',r.letter_grade,'grade_point',r.grade_point) from public.course_results r join public.course_offerings co on co.id=r.course_offering_id where r.institution_id=p_inst and r.result_status='published' and coalesce(r.published_at,r.created_at)::date between p_from and p_to and (p_period is null or co.academic_period_id=p_period) and (r.letter_grade is null or r.grade_point is null)
 union all select 'ACA03','Graduated student missing approved graduation record','high',s.id::text,jsonb_build_object('student_number',s.student_number) from public.students s where s.institution_id=p_inst and s.status='graduated' and not exists(select 1 from public.graduation_reviews g where g.student_id=s.id and g.institution_id=p_inst and g.decision='graduated' and g.approved_by is not null and g.approved_at is not null and g.graduation_date is not null)
 union all select 'ACA04','Graduated review has outstanding trails or credit shortfall','high',g.id::text,jsonb_build_object('student_id',g.student_id,'trails',g.outstanding_trails,'earned',g.credits_earned,'required',g.credits_required) from public.graduation_reviews g where g.institution_id=p_inst and g.decision='graduated' and (g.outstanding_trails>0 or g.credits_required is null or g.credits_earned<g.credits_required)
 union all select 'ACC01','Additional role without approved independent request','high',m.id::text,jsonb_build_object('user_id',m.user_id,'role',rr.code) from public.unimis_additional_roles116 a join public.institution_users m on m.id=a.institution_user_id join public.roles rr on rr.id=a.role_id left join public.unimis_access_requests116 q on q.id=a.request_id where m.institution_id=p_inst and (q.id is null or q.status not in('approved','executed') or q.role_id is distinct from a.role_id or q.institution_id is distinct from m.institution_id or q.target_user_id is distinct from m.user_id or q.reviewed_by is null or q.reviewed_by=q.requested_by or q.reviewed_by=m.user_id)
 union all select 'ACC02','Platform operator has a school membership','high',m.id::text,jsonb_build_object('user_id',m.user_id,'role_id',m.role_id) from public.institution_users m join public.unimis_platform_operators116 o on o.user_id=m.user_id and o.active where m.institution_id=p_inst
 ),catalog(code,title,severity,scope) as(values('FIN01','Posted journals balance and have lines','high','Financial date range'),('FIN02','Completed cash payments have receipts','high','Financial date range'),('FIN03','Completed cash payments have source journals','high','Financial date range'),('FIN04','Voids have reversal postings and excluded status','high','Void/payment date range'),('FIN05','Invoice paid totals reconcile','medium','Invoice date range; lifetime completed payments'),('FIN06','Application fee income posting','high','Verified GHS fees; verification/payment date'),('ACA01','Published results have approval evidence','medium','Publication date and selected semester'),('ACA02','Published results contain grades','high','Publication date and selected semester'),('ACA03','Graduated students have approval evidence','high','Current graduation state; date independent'),('ACA04','Graduation credits and trails reconcile','high','Current graduation state; date independent'),('ACC01','Additional role approval provenance','high','Current access state; date independent'),('ACC02','Technical/school authority separation','high','Current access state; date independent'))
 select jsonb_agg(jsonb_build_object('code',c.code,'title',c.title,'severity',c.severity,'scope',c.scope,'count',(select count(*) from evidence e where e.code=c.code),'sample',coalesce((select jsonb_agg(to_jsonb(s)) from(select reference,detail from evidence e where e.code=c.code order by reference limit 100)s),'[]'::jsonb)) order by c.code) into checks from catalog c;
 insert into public.unimis_audit_runs151(institution_id,actor,from_date,to_date,academic_period_id,checks) values(p_inst,auth.uid(),p_from,p_to,p_period,checks) returning id into rid;
 return jsonb_build_object('id',rid,'actor',auth.uid(),'checks',checks,'from_date',p_from,'to_date',p_to,'academic_period_id',p_period,'created_at',now());end $$;
create function public.unimis_audit_workspace151(p_inst uuid) returns jsonb language plpgsql security definer set search_path='' as $$begin
 if not public.unimis_audit_allowed151(p_inst) then raise exception 'School Auditor or Owner required';end if;
 return jsonb_build_object('school',(select name from public.institutions where id=p_inst),'periods',coalesce((select jsonb_agg(jsonb_build_object('id',ap.id,'name',ay.name||' • '||ap.name)) from public.academic_periods ap join public.academic_years ay on ay.id=ap.academic_year_id where ap.institution_id=p_inst),'[]'::jsonb),'runs',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from public.unimis_audit_runs151 where institution_id=p_inst order by created_at desc limit 30)x),'[]'::jsonb),'findings',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from public.unimis_audit_findings151 where institution_id=p_inst order by created_at desc limit 200)x),'[]'::jsonb),'access',coalesce((select jsonb_agg(to_jsonb(x)) from(select id,action,role_id,status,reason,requested_by,reviewed_by,review_note,created_at from public.unimis_access_requests116 where institution_id=p_inst order by created_at desc limit 200)x),'[]'::jsonb),'events',coalesce((select jsonb_agg(to_jsonb(x)) from(select id,action,entity_type,entity_id,user_id,created_at from public.audit_logs where institution_id=p_inst order by created_at desc limit 200)x),'[]'::jsonb),'security_events',coalesce((select jsonb_agg(to_jsonb(x)) from(select id,event_type,user_id,created_at from public.security_events where institution_id=p_inst order by created_at desc limit 200)x),'[]'::jsonb),'support_events',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from public.unimis_technical_events151 where institution_id=p_inst order by created_at desc limit 100)x),'[]'::jsonb));end $$;
create function public.unimis_audit_finding151(p_run uuid,p_code text,p_reference text,p_severity text,p_finding text,p_recommendation text) returns void language plpgsql security definer set search_path='' as $$
declare inst uuid;begin
 select institution_id into inst from public.unimis_audit_runs151 where id=p_run;
 if inst is null or not public.unimis_audit_allowed151(inst) then raise exception 'School Auditor or Owner required';end if;
 if length(btrim(p_finding))<10 or length(btrim(p_recommendation))<10 or nullif(btrim(p_reference),'') is null or not exists(select 1 from public.unimis_audit_runs151 r cross join lateral jsonb_array_elements(r.checks)c where r.id=p_run and c->>'code'=p_code) then raise exception 'Valid check, reference, finding and recommendation required';end if;
 insert into public.unimis_audit_findings151(run_id,institution_id,actor,check_code,record_reference,severity,finding,recommendation) values(p_run,inst,auth.uid(),p_code,p_reference,p_severity,p_finding,p_recommendation);end $$;

create function public.unimis_audit_evidence151(p_inst uuid,p_code text,p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;begin
 if not public.unimis_audit_allowed151(p_inst) then raise exception 'School Auditor or Owner required';end if;
 if p_code='FIN01' then
 select jsonb_build_object('journal',jsonb_build_object('id',j.id,'number',j.journal_number,'date',j.journal_date,'status',j.status,'reference',j.reference,'created_by',j.created_by),'lines',coalesce((select jsonb_agg(jsonb_build_object('account_id',l.account_id,'debit',l.debit,'credit',l.credit,'description',l.description)) from public.finance_journal_lines l where l.journal_id=j.id and l.institution_id=p_inst),'[]'::jsonb)) into result from public.finance_journals j where j.id=p_id and j.institution_id=p_inst;
 elsif p_code in('FIN02','FIN03','FIN04') then
 select jsonb_build_object('payment',jsonb_build_object('id',p.id,'reference',p.payment_reference,'student_id',p.student_id,'invoice_id',p.invoice_id,'date',p.payment_date,'amount',p.amount,'currency',p.currency_code,'status',p.status,'voided_at',p.voided_at,'void_reason',p.void_reason),'receipts',coalesce((select jsonb_agg(jsonb_build_object('number',r.receipt_number,'issued_at',r.issued_at)) from public.payment_receipts r where r.payment_id=p.id and r.institution_id=p_inst),'[]'::jsonb),'journals',coalesce((select jsonb_agg(jsonb_build_object('number',j.journal_number,'date',j.journal_date,'status',j.status,'source_type',j.source_type)) from public.finance_journals j where j.source_id=p.id and j.institution_id=p_inst),'[]'::jsonb)) into result from public.student_payments p where p.id=p_id and p.institution_id=p_inst;
 elsif p_code='FIN05' then
 select jsonb_build_object('invoice',i.invoice_number,'date',i.invoice_date,'student_id',i.student_id,'total',i.total_amount,'paid',i.amount_paid,'balance',i.balance,'currency',i.currency_code,'status',i.status,'payments',coalesce((select jsonb_agg(jsonb_build_object('reference',p.payment_reference,'amount',p.amount,'status',p.status,'currency',p.currency_code)) from public.student_payments p where p.invoice_id=i.id and p.institution_id=p_inst),'[]'::jsonb)) into result from public.student_invoices i where i.id=p_id and i.institution_id=p_inst;
 elsif p_code='FIN06' then
 select jsonb_build_object('application_id',p.application_id,'reference',p.provider_reference,'amount',p.amount,'currency',p.currency,'status',p.status,'verified_at',p.verified_at) into result from public.admission_application_payments p where p.id=p_id and p.institution_id=p_inst;
 elsif p_code in('ACA01','ACA02') then
 select jsonb_build_object('result_id',r.id,'student_number',s.student_number,'course',c.code,'period',ap.name,'score',r.total_score,'grade',r.letter_grade,'grade_point',r.grade_point,'status',r.result_status,'submitted_by',r.submitted_by,'approved_by',r.approved_by,'approved_at',r.approved_at,'published_at',r.published_at) into result from public.course_results r join public.students s on s.id=r.student_id and s.institution_id=p_inst join public.course_offerings co on co.id=r.course_offering_id and co.institution_id=p_inst join public.courses c on c.id=co.course_id and c.institution_id=p_inst join public.academic_periods ap on ap.id=co.academic_period_id and ap.institution_id=p_inst where r.id=p_id and r.institution_id=p_inst;
 elsif p_code='ACA03' then
 select jsonb_build_object('student_number',s.student_number,'status',s.status,'reviews',coalesce((select jsonb_agg(to_jsonb(g)) from public.graduation_reviews g where g.student_id=s.id and g.institution_id=p_inst),'[]'::jsonb)) into result from public.students s where s.id=p_id and s.institution_id=p_inst;
 elsif p_code='ACA04' then select to_jsonb(g) into result from public.graduation_reviews g where g.id=p_id and g.institution_id=p_inst;
 elsif p_code in('ACC01','ACC02') then select jsonb_build_object('membership_id',m.id,'user_id',m.user_id,'role_id',m.role_id,'status',m.status,'additional_roles',coalesce((select jsonb_agg(to_jsonb(a)) from public.unimis_additional_roles116 a where a.institution_user_id=m.id),'[]'::jsonb)) into result from public.institution_users m where m.id=p_id and m.institution_id=p_inst;
 else raise exception 'Unknown audit check';end if;
 if result is null then raise exception 'Evidence not found in your school';end if;return result;end $$;

do $$declare fn record;begin for fn in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like '%151' loop execute format('revoke all on function %s from public,anon',fn.signature);execute format('grant execute on function %s to authenticated',fn.signature);end loop;end $$;
notify pgrst,'reload schema';
commit;
